Script:
// Meteor shower - shooting stars streak in from the top edge and arc down
// across the sky under gravity, trailing bright tails.
@scene fps=30 bg=#000010 trail=0.8 size=48x32

emit meteors
  rate    = 1 per ${interval}s
  origin  = x:rand y:top
  vel     = dir:right speed:${speed} spread:14
  gravity = down 26
  color   = pick(#bfe0ff,#ffffff,#ffe6bf,#d9ecff)
  life    = 2.2s
